    enemies.forEach(e => e.draw());
  };

  const s = () => {
    enemyColors.push(enemyColors.shift()); // shift color each frame
    if (enemies.length === 0) {
      enemies = new Array(Math.pow(level, 2)).fill().map((_, i) => {
        const r = (i % Math.sqrt(level) + 1) * 20;
        const c = Math.floor(i / Math.sqrt(level)) * 20 + 20;
